/**
 * kit sdk generate [--target name]   every target of kit.sdk.json (or one): its OpenAPI 3.1 contract → a typed client,
 *                                    types, CLI and Python client generated by @saasreport/forge, into target.out, with
 *                                    forge.manifest.json (contract sha256, @saasreport/forge and its origin, sha256 per file)
 * kit sdk check                      = kit check sdk: missing, stale, hand-edited, duplicate hand-written clients
 * (docs/SDK.md; the generator is compulsory: generated files are never written or edited by hand)
 */
import { CliError } from "../args.js";
import { loadSdkConfig, generateTarget, writeTarget, FORGE } from "../../../sdk/src/index.js";
import { bundled, checkSdkRepo, loadCanon } from "../canon/index.js";
import { formatProblems } from "@saasreport/core/schema";
import { existsSync } from "node:fs";
import { join } from "node:path";

export async function sdk(io, { _: [sub] = [], flags }) {
  const kit = bundled();
  const validate = (value, name) => formatProblems(kit.validator.validate(value, kit.byName(name)));
  if (sub === "generate") {
    const { config, problems } = loadSdkConfig(io.cwd, { validate });
    if (!config) throw new CliError(problems.length ? problems.map((p) => p.problem).join("; ") : "no kit.sdk.json: declare the targets (docs/SDK.md)", 1);
    if (problems.length) throw new CliError(problems.map((p) => p.problem).join("; "), 1);
    const targets = config.targets.filter((t) => !flags.target || t.name === String(flags.target));
    if (!targets.length) throw new CliError(`no target ${flags.target}`, 2);
    let failed = 0;
    for (const t of targets) {
      const g = await generateTarget(io.cwd, t, config.targets);
      if (g.problems.length) {
        failed++;
        io.err(`kit sdk generate: ${t.name}: ${g.problems.length} problem${g.problems.length === 1 ? "" : "s"} in ${t.contract}`);
        for (const p of g.problems) io.err(`  - ${p}`);
        continue;
      }
      try { writeTarget(io.cwd, t, g.files, config.targets); } catch (e) { failed++; io.err(`kit sdk generate: ${e.message}`); continue; }
      io.out(`kit sdk generate: ${t.name}: ${g.operations} operations from ${t.contract} → ${t.out} (${g.files.length} files; @saasreport/forge ${FORGE.version}, origin ${FORGE.origin.commit.slice(0, 12)})`);
    }
    return failed ? 1 : 0;
  }
  if (sub === "check") {
    const canon = existsSync(join(io.cwd, "kit.canon.json")) ? loadCanon(io.cwd, kit).canon : null;
    const r = await checkSdkRepo(io.cwd, canon, kit);
    io[r.ok ? "out" : "err"](`${r.ok ? "ok" : "FAIL"} sdk: ${r.summary}${r.problems.length ? ` — ${r.problems.length} problem${r.problems.length === 1 ? "" : "s"}` : ""}`);
    for (const p of r.problems) io.err(`  - ${p.file}: ${p.problem}`);
    return r.ok ? 0 : 1;
  }
  throw new CliError(`unknown sdk command "${sub ?? ""}" (generate, check)`, 2);
}
